        | SessionYardDocumentRead.Found document -> SessionYardDocumentLoaded.Loaded(start document)
        | SessionYardDocumentRead.Missing -> SessionYardDocumentLoaded.DocumentMissing(start empty)
        | SessionYardDocumentRead.ReadFailed reason -> SessionYardDocumentLoaded.LoadFailed reason

    let private withEntry (session: SessionYardDocumentSession) (entry: SessionYardEntry) =
