        | Some pending -> SessionYardCreated.Unreconciled pending
        | None when Map.containsKey id session.Working.Entries -> SessionYardCreated.AlreadyExists id
        | None -> SessionYardCreated.Created(withEntry session { Id = id; Revision = 0L; State = SessionYardState.Closed })

    /// Decides one command against one entry and applies it to the working copy. `expected`, when
    /// given, is the entry revision the caller acted on. Refused while a save is unknown.
    let apply (rules: SessionYardRules) (session: SessionYardDocumentSession) (id: SessionYardId) (expected: int64 option) (command: SessionYardCommand) : SessionYardCommandOutcome =
        match session.Pending, Map.tryFind id session.Working.Entries, expected with
        | Some pending, _, _ -> SessionYardCommandOutcome.Unreconciled pending
        | None, None, _ -> SessionYardCommandOutcome.EntryNotFound id
        | None, Some entry, Some revision when revision <> entry.Revision -> SessionYardCommandOutcome.EntryStale(id, revision, entry.Revision)
        | None, Some entry, _ ->
