            | Error refusal -> SessionYardCommandOutcome.Refused(refusal, entry)
            | Ok decision ->
                SessionYardCommandOutcome.Applied(withEntry session { entry with Revision = entry.Revision + 1L; State = decision.Next }, decision)

    let private write (store: ISessionYardDocumentStore) (session: SessionYardDocumentSession) (operation: SessionYardOperationId) =
        match store.Write(operation, session.Stored.Version, session.Working) with
        | SessionYardDocumentWrite.Written version ->
            let stored = { session.Working with Version = Some version }
